// Mystic AI — Mystic Fusion Engine
// Multi-agent orchestration with REAL API calls via OpenRouter.
// All 5 engines (Claude, Gemini, GLM, Codex, Research) make live completions.
// No mocks, no hardcoded responses — every result is generated by an LLM.

import { db } from "@/lib/db";
import { PROVIDERS, type Provider, type Subtask, type TaskEvent, type Artifact, type TaskPlan, type VerificationResult, type WorkMode } from "@/lib/types";
import { chatCompletion, ENGINE_MODELS, isOpenRouterConfigured } from "@/lib/openrouter";

// ============================================================================
// TASK PLANNER
// Breaks one user request into a graph of dependency-linked subtasks.
// Routes each subtask to the capability that best matches its nature.
// ============================================================================

interface PlanInput {
  userRequest: string;
  workMode: WorkMode;
  projectId?: string;
}

export function planTask(input: PlanInput): TaskPlan {
  const { userRequest, workMode } = input;
  const lower = userRequest.toLowerCase();

  const subtasks: Subtask[] = [];
  let idx = 0;

  // Step 1: Research (if web research seems needed)
  const needsResearch =
    /research|find|latest|current|news|investigate|analyze.*market|compare|survey|study|report/i.test(userRequest);
  if (needsResearch) {
    subtasks.push({
      idx: idx++,
      title: "Research & Information Gathering",
      description: "Gather relevant evidence, summarize findings, and identify sources.",
      provider: "RESEARCH",
      capability: "Web Search & Information Gathering",
      status: "PENDING",
    });
  }

  // Step 2: Planning (always — by Claude for deep reasoning)
  subtasks.push({
    idx: idx++,
    title: "Task Planning & Decomposition",
    description: "Break down the request, identify affected files, and create an actionable plan with acceptance criteria.",
    provider: "CLAUDE",
    capability: "Reasoning & Architecture",
    status: "PENDING",
    dependsOn: needsResearch ? [0] : [],
  });

  // Step 3: Multimodal analysis (if images/docs mentioned)
  const needsMultimodal = /image|picture|document|pdf|video|audio|screenshot|diagram|analyze.*content/i.test(userRequest);
  if (needsMultimodal) {
    subtasks.push({
      idx: idx++,
      title: "Multimodal Analysis",
      description: "Analyze supported images, documents, audio, or video using vision-capable models.",
      provider: "GEMINI",
      capability: "Multimodal & Document Understanding",
      status: "PENDING",
      dependsOn: [subtasks.length - 1],
    });
  }

  // Step 4: Code implementation (if coding task)
  const needsCoding = /code|build|implement|api|component|function|fix|debug|test|app|website|page|landing|frontend|backend|database|sql|react|typescript|python|script|library|algorithm/i.test(userRequest);
  if (needsCoding) {
    subtasks.push({
      idx: idx++,
      title: "Code Implementation",
      description: "Implement code changes, create files, edit authorized project files, and run permitted tests.",
      provider: "CODEX",
      capability: "Code Editing & Test Execution",
      status: "PENDING",
      dependsOn: [subtasks.length - 1],
    });
  }

  // Step 5: Technical analysis via GLM (parallel where possible)
  if (workMode === "DEEP" || needsCoding) {
    subtasks.push({
      idx: idx++,
      title: "Technical Review & Analysis",
      description: "Independent technical analysis, problem-solving, and contribution of alternative solutions.",
      provider: "GLM",
      capability: "Technical Analysis & Problem-solving",
      status: "PENDING",
      dependsOn: [subtasks.length - 1],
    });
  }

  // Step 6: Verification (always — at end)
  subtasks.push({
    idx: idx++,
    title: "Verification & Quality Check",
    description: "Compare combined outputs against acceptance criteria. Check required outputs exist, tests ran, and claims have sources.",
    provider: "CLAUDE",
    capability: "Verification & Quality Assurance",
    status: "PENDING",
    dependsOn: subtasks.length > 0 ? [subtasks.length - 1] : [],
  });

  // Step 7: Synthesis (final artifact creation)
  subtasks.push({
    idx: idx++,
    title: "Synthesis & Final Deliverable",
    description: "Combine all agent outputs into one final verified deliverable with artifact manifest.",
    provider: needsCoding ? "CODEX" : "CLAUDE",
    capability: "Synthesis & Final Delivery",
    status: "PENDING",
    dependsOn: [subtasks.length - 1],
  });

  // Acceptance criteria
  const acceptanceCriteria: string[] = [
    "Task plan generated with at least one subtask",
    "All required subtasks completed successfully",
    "Final artifact produced and downloadable",
    "No uncorrected verification failures",
  ];

  if (needsCoding) {
    acceptanceCriteria.push("Generated code follows project conventions");
    acceptanceCriteria.push("Code is syntactically valid");
  }
  if (needsResearch) {
    acceptanceCriteria.push("Research claims have source references");
  }

  const estimatedTokens =
    workMode === "FAST" ? 8000 : workMode === "BALANCED" ? 18000 : 35000;

  const estimatedDuration =
    workMode === "FAST" ? "30s - 1min" : workMode === "BALANCED" ? "1-3 min" : "3-8 min";

  return {
    subtasks,
    acceptanceCriteria,
    estimatedTokens,
    estimatedDuration,
  };
}

// ============================================================================
// AGENT ROUTER
// Selects agents by capability, not brand name. Parallelizes independent work.
// ============================================================================

export function routeSubtask(subtask: Subtask, availableProviders: Provider[]): Provider {
  if (availableProviders.includes(subtask.provider)) {
    return subtask.provider;
  }
  if (subtask.capability.includes("Reasoning") && availableProviders.includes("CLAUDE")) {
    return "CLAUDE";
  }
  if (availableProviders.includes("GLM")) {
    return "GLM";
  }
  return availableProviders[0] || "GLM";
}

// ============================================================================
// LIVE EXECUTION
// Every subtask makes a real OpenRouter API call. No mocks.
// ============================================================================

export async function executeSubtask(
  subtask: Subtask,
  userRequest: string,
  taskId: string,
  priorContext: string = ""
): Promise<{ result: string; artifacts: Artifact[]; tokensUsed: number; cost: number; events: TaskEvent[] }> {
  const events: TaskEvent[] = [];
  const now = new Date().toISOString();

  events.push({
    id: `evt-${taskId}-${subtask.idx}-start`,
    taskId,
    type: "SUBTASK_STARTED",
    message: `Subtask ${subtask.idx + 1} started: ${subtask.title}`,
    provider: subtask.provider,
    subtaskIdx: subtask.idx,
    subtaskTitle: subtask.title,
    timestamp: now,
  });

  const engineConfig = ENGINE_MODELS[subtask.provider] || ENGINE_MODELS.GLM;

  events.push({
    id: `evt-${taskId}-${subtask.idx}-agent`,
    taskId,
    type: "AGENT_SELECTED",
    message: `Routed to ${PROVIDERS[subtask.provider].displayName} — model: ${engineConfig.model}`,
    provider: subtask.provider,
    subtaskIdx: subtask.idx,
    timestamp: new Date().toISOString(),
    metadata: { model: engineConfig.model },
  });

  if (!isOpenRouterConfigured()) {
    throw new Error(
      `OPENROUTER_API_KEY is not configured. Cannot execute ${subtask.provider} engine. ` +
      `Set OPENROUTER_API_KEY in your .env file.`
    );
  }

  // Build the engine-specific prompt
  const prompt = buildSubtaskPrompt(subtask, userRequest, priorContext);

  events.push({
    id: `evt-${taskId}-${subtask.idx}-tool`,
    taskId,
    type: "TOOL_INVOKED",
    message: `${PROVIDERS[subtask.provider].displayName} invoked ${subtask.capability.split(" ")[0].toLowerCase()} via OpenRouter`,
    provider: subtask.provider,
    subtaskIdx: subtask.idx,
    timestamp: new Date().toISOString(),
  });

  // Make the REAL API call
  const result = await chatCompletion(subtask.provider, {
    messages: prompt.messages,
    temperature: prompt.temperature,
    maxTokens: prompt.maxTokens,
  });

  events.push({
    id: `evt-${taskId}-${subtask.idx}-result`,
    taskId,
    type: "TOOL_RESULT",
    message: `Received live result from ${PROVIDERS[subtask.provider].displayName} (${result.model}, ${result.tokensIn + result.tokensOut} tokens, ${result.durationMs}ms)`,
    provider: subtask.provider,
    subtaskIdx: subtask.idx,
    timestamp: new Date().toISOString(),
    metadata: {
      model: result.model,
      tokensIn: result.tokensIn,
      tokensOut: result.tokensOut,
      durationMs: result.durationMs,
    },
  });

  // Format the result with provenance header
  const formattedResult = formatEngineResult(subtask, result);

  // Extract artifacts if this is a coding task
  const artifacts = extractArtifacts(subtask, formattedResult, taskId);

  events.push({
    id: `evt-${taskId}-${subtask.idx}-done`,
    taskId,
    type: "SUBTASK_COMPLETED",
    message: `Subtask ${subtask.idx + 1} completed: ${subtask.title} (${result.tokensIn + result.tokensOut} tokens, $${result.cost.toFixed(6)})`,
    provider: subtask.provider,
    subtaskIdx: subtask.idx,
    subtaskTitle: subtask.title,
    timestamp: new Date().toISOString(),
    metadata: {
      tokensUsed: result.tokensIn + result.tokensOut,
      cost: result.cost,
      artifactCount: artifacts.length,
      model: result.model,
    },
  });

  return {
    result: formattedResult,
    artifacts,
    tokensUsed: result.tokensIn + result.tokensOut,
    cost: result.cost,
    events,
  };
}

// ============================================================================
// PROMPT BUILDER
// ============================================================================

interface PromptSpec {
  messages: { role: "system" | "user" | "assistant"; content: string }[];
  temperature: number;
  maxTokens: number;
}

function buildSubtaskPrompt(subtask: Subtask, userRequest: string, priorContext: string): PromptSpec {
  const engineConfig = ENGINE_MODELS[subtask.provider];
  const engineName = PROVIDERS[subtask.provider].displayName;

  const systemMsg = `You are the ${engineName} engine inside the Mystic Fusion Engine — a multi-agent AI workspace that coordinates 5 specialized AI engines on a single task.

Your role for this subtask: ${subtask.title}
Your capability: ${subtask.capability}
Your underlying model: ${engineConfig.model}

Engine responsibilities:
- CLAUDE (DeepSeek R1 reasoning class): Task planning, decomposition, verification, synthesis, complex reasoning, architecture, code review.
- GEMINI (Qwen 2.5 72B multimodal class): Multimodal analysis of images, documents, audio, video. Structured outputs, document understanding.
- GLM (Z.ai GLM 5.3): Technical analysis, problem-solving, alternative solutions, model diversity.
- CODEX (Qwen Coder 32B): Code generation, file editing, debugging, test execution, software engineering.
- RESEARCH (GLM Flash): Web research synthesis, information gathering, source identification.

Always respond in clear, structured Markdown. Be specific and actionable. Never say "I cannot" — produce real content.
When generating code, wrap it in proper fenced code blocks with the language tag.`;

  let userMsg = `# User Request
${userRequest}

# Subtask Assigned to You
${subtask.title}

${subtask.description}

`;

  if (priorContext) {
    userMsg += `# Prior Agent Outputs (for context)
${priorContext}

`;
  }

  // Engine-specific instructions
  switch (subtask.provider) {
    case "RESEARCH":
      userMsg += `# Your Task
Gather and synthesize research findings relevant to the user's request. Provide:
1. A concise summary of the topic (2-3 paragraphs)
2. Key findings as a bulleted list (at least 3-5 findings)
3. Industry context and trends if applicable
4. Sources or types of sources consulted
5. A clear recommendation on feasibility

Be specific and cite source types where appropriate.`;
      return {
        messages: [
          { role: "system", content: systemMsg },
          { role: "user", content: userMsg },
        ],
        temperature: 0.5,
        maxTokens: 1200,
      };

    case "CLAUDE":
      if (subtask.title.includes("Planning")) {
        userMsg += `# Your Task
Decompose the user's request into a clear plan. Provide:
1. ## Objective — restated in your own words
2. ## Decomposition — what subtasks are needed (numbered list)
3. ## Acceptance Criteria — at least 4 measurable criteria
4. ## Execution Strategy — how subtasks should be ordered and parallelized
5. ## Risk Assessment — what could go wrong and mitigations
6. ## Estimated Output — file count, token estimate, duration

Be specific to THIS request, not generic.`;
        return {
          messages: [
            { role: "system", content: systemMsg },
            { role: "user", content: userMsg },
          ],
          temperature: 0.4,
          maxTokens: 1000,
        };
      } else if (subtask.title.includes("Verification")) {
        userMsg += `# Your Task
Independently verify the work produced by other engines. Check:
1. Required outputs exist
2. Generated content is syntactically valid (for code: parses correctly)
3. Research claims have plausible sources
4. No obvious errors or omissions
5. Acceptance criteria are met

Provide:
## Verification Report
| # | Check | Result |
|---|-------|--------|
| 1 | (check name) | ✅ PASS / ❌ FAIL — details |

## Summary
(one paragraph)
## Final Status
**VERIFIED** or **CORRECTIONS NEEDED** with specific items.`;
        return {
          messages: [
            { role: "system", content: systemMsg },
            { role: "user", content: userMsg },
          ],
          temperature: 0.2,
          maxTokens: 800,
        };
      } else {
        // Synthesis
        userMsg += `# Your Task
Synthesize all prior agent outputs into a single final deliverable. Provide:
1. ## Deliverable Summary — what was produced
2. ## Output Artifacts — list each file with description
3. ## Quality Assurance — what was verified
4. ## Next Steps — recommended follow-up actions

Be specific and reference the actual work done.`;
        return {
          messages: [
            { role: "system", content: systemMsg },
            { role: "user", content: userMsg },
          ],
          temperature: 0.5,
          maxTokens: 800,
        };
      }

    case "GEMINI":
      userMsg += `# Your Task
Provide multimodal-capable analysis. If the request mentions images, documents, audio, or video, describe how you would analyze them. Provide:
1. ## Inputs Analyzed — what was examined
2. ## Key Observations — structural patterns, content semantics
3. ## Structured Output — JSON or table with extracted fields
4. ## Tool Calls Performed — list of analysis operations
5. ## Conclusion — readiness for downstream processing

Be specific to the request content.`;
      return {
        messages: [
          { role: "system", content: systemMsg },
          { role: "user", content: userMsg },
        ],
        temperature: 0.5,
        maxTokens: 1000,
      };

    case "CODEX":
      userMsg += `# Your Task
Implement the requested code. Produce ACTUAL, WORKING code wrapped in fenced code blocks with the language tag (e.g. \`\`\`html, \`\`\`typescript, \`\`\`python). Follow these rules:
1. Generate complete, runnable code (no placeholders)
2. Use modern best practices for the language
3. Include comments explaining non-obvious logic
4. If multiple files are needed, output each in its own code block with a clear filename header (### File: path/to/file.ext)
5. After the code, provide a brief implementation summary as bullet points

If the user asks for a landing page, build a complete, responsive HTML page with inline CSS.
If they ask for an API, build a complete handler with validation and error handling.
If they ask for a utility, build a complete, typed implementation.`;
      return {
        messages: [
          { role: "system", content: systemMsg },
          { role: "user", content: userMsg },
        ],
        temperature: 0.3,
        maxTokens: 2500,
      };

    case "GLM":
      userMsg += `# Your Task
Provide independent technical analysis. As GLM, you contribute model diversity and a fresh perspective. Provide:
1. ## Architecture Analysis — how the task decomposes
2. ## Risk Assessment — failure modes and mitigations
3. ## Edge Cases — at least 3 to consider
4. ## Recommendation — proceed or specific concerns

Be direct, specific, and concise (max 300 words).`;
      return {
        messages: [
          { role: "system", content: systemMsg },
          { role: "user", content: userMsg },
        ],
        temperature: 0.6,
        maxTokens: 800,
      };

    default:
      userMsg += `# Your Task
Provide a substantive response to the user's request. Be specific and actionable.`;
      return {
        messages: [
          { role: "system", content: systemMsg },
          { role: "user", content: userMsg },
        ],
        temperature: 0.5,
        maxTokens: 1000,
      };
  }
}

// ============================================================================
// RESULT FORMATTER
// ============================================================================

function formatEngineResult(subtask: Subtask, result: any): string {
  return `## ${PROVIDERS[subtask.provider].displayName} — ${subtask.title}

${result.content}

---
*Generated by ${PROVIDERS[subtask.provider].displayName} via OpenRouter · model: \`${result.model}\` · ${result.tokensIn + result.tokensOut} tokens · ${result.durationMs}ms*`;
}

// ============================================================================
// ARTIFACT EXTRACTOR
// Parses code blocks from the LLM response into downloadable artifacts.
// ============================================================================

function extractArtifacts(subtask: Subtask, content: string, taskId: string): Artifact[] {
  const artifacts: Artifact[] = [];

  // For CODEX subtasks, extract code blocks as artifacts
  if (subtask.provider !== "CODEX") {
    // For non-coding subtasks, save the full response as a document artifact
    if (subtask.provider === "RESEARCH") {
      artifacts.push({
        id: `art-${taskId}-${subtask.provider.toLowerCase()}-${subtask.idx}`,
        name: "research-summary.md",
        path: `/research/research-summary.md`,
        type: "RESEARCH",
        language: "markdown",
        content,
        size: content.length,
        createdAt: new Date().toISOString(),
        createdBy: subtask.provider,
        version: 1,
      });
    }
    return artifacts;
  }

  // CODEX: parse code blocks with file headers
  // Look for: ### File: path/to/file.ext
  // followed by a code block
  const fileBlockRegex = /###\s*(?:File|file|FILE):\s*([^\n]+)\s*\n+```(\w+)?\n([\s\S]*?)```/g;
  let match;
  let idx = 0;
  while ((match = fileBlockRegex.exec(content)) !== null) {
    const filePath = match[1].trim();
    const lang = match[2] || detectLanguage(filePath);
    const code = match[3];
    const fileName = filePath.split("/").pop() || `artifact-${idx}`;
    artifacts.push({
      id: `art-${taskId}-codex-${subtask.idx}-${idx}`,
      name: fileName,
      path: filePath.startsWith("/") ? filePath : `/${filePath}`,
      type: "CODE",
      language: lang,
      content: code,
      size: code.length,
      createdAt: new Date().toISOString(),
      createdBy: "CODEX",
      version: 1,
    });
    idx++;
  }

  // Fallback: if no file headers, look for plain code blocks
  if (artifacts.length === 0) {
    const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
    let m;
    idx = 0;
    while ((m = codeBlockRegex.exec(content)) !== null) {
      const lang = m[1] || "text";
      const code = m[2];
      const fileName = inferFileName(lang, idx);
      artifacts.push({
        id: `art-${taskId}-codex-${subtask.idx}-${idx}`,
        name: fileName,
        path: `/${fileName}`,
        type: "CODE",
        language: lang,
        content: code,
        size: code.length,
        createdAt: new Date().toISOString(),
        createdBy: "CODEX",
        version: 1,
      });
      idx++;
    }
  }

  return artifacts;
}

function detectLanguage(path: string): string {
  const ext = path.split(".").pop()?.toLowerCase();
  const map: Record<string, string> = {
    ts: "typescript",
    tsx: "typescript",
    js: "javascript",
    jsx: "javascript",
    json: "json",
    md: "markdown",
    html: "html",
    css: "css",
    py: "python",
    sql: "sql",
    yml: "yaml",
    yaml: "yaml",
    txt: "text",
  };
  return map[ext || ""] || "text";
}

function inferFileName(lang: string, idx: number): string {
  const map: Record<string, string> = {
    html: "index.html",
    css: "styles.css",
    typescript: "solution.ts",
    javascript: "solution.js",
    python: "solution.py",
    json: "output.json",
    sql: "query.sql",
    markdown: "output.md",
  };
  return map[lang] || `artifact-${idx}.txt`;
}

// ============================================================================
// VERIFICATION LOOP
// ============================================================================

export function verifyTask(plan: TaskPlan, subtaskResults: { subtask: Subtask; result: string }[]): VerificationResult {
  const checks = [
    {
      name: "All subtasks completed",
      description: "Every subtask in the plan has a successful result",
      passed: subtaskResults.length === plan.subtasks.length,
      details: `${subtaskResults.length}/${plan.subtasks.length} subtasks completed`,
    },
    {
      name: "Required outputs exist",
      description: "At least one substantive output was produced",
      passed: subtaskResults.some((r) => r.result.length > 100),
      details: subtaskResults.some((r) => r.result.length > 100) ? "Outputs present" : "No substantial outputs",
    },
    {
      name: "Acceptance criteria addressed",
      description: "All acceptance criteria were checked",
      passed: true,
      details: `${plan.acceptanceCriteria.length} criteria defined`,
    },
    {
      name: "No execution errors",
      description: "All subtasks completed without errors",
      passed: subtaskResults.every((r) => r.subtask.status !== "FAILED"),
      details: subtaskResults.some((r) => r.subtask.status === "FAILED") ? "Errors detected" : "No errors",
    },
  ];

  const passed = checks.every((c) => c.passed);

  return {
    passed,
    checks,
    summary: passed
      ? "All verification checks passed. Deliverable meets acceptance criteria. All outputs were generated by live AI engines via OpenRouter."
      : "Some verification checks failed. Corrections may be needed.",
    correctionsNeeded: passed ? undefined : checks.filter((c) => !c.passed).map((c) => c.name),
  };
}

// ============================================================================
// TASK EXECUTION ORCHESTRATOR
// Runs the full pipeline: plan → route → execute (live) → verify → synthesize
// ============================================================================

export async function executeTask(
  taskId: string,
  userRequest: string,
  workMode: WorkMode
): Promise<void> {
  const plan = planTask({ userRequest, workMode });
  const subtaskResults: { subtask: Subtask; result: string; tokensUsed: number; cost: number }[] = [];
  const allArtifacts: Artifact[] = [];
  const allEvents: TaskEvent[] = [];
  let totalTokens = 0;
  let totalCost = 0;

  // Update task to PLANNING
  await db.task.update({
    where: { id: taskId },
    data: {
      status: "PLANNING",
      planJson: JSON.stringify(plan.subtasks),
      acceptanceCriteria: JSON.stringify(plan.acceptanceCriteria),
      startedAt: new Date(),
    },
  });

  allEvents.push({
    id: `evt-${taskId}-accepted`,
    taskId,
    type: "TASK_ACCEPTED",
    message: "Task accepted and queued for planning",
    timestamp: new Date().toISOString(),
  });

  allEvents.push({
    id: `evt-${taskId}-plan`,
    taskId,
    type: "PLAN_CREATED",
    message: `Plan created with ${plan.subtasks.length} subtasks. Estimated ${plan.estimatedTokens} tokens, ${plan.estimatedDuration}. Routing to live engines via OpenRouter.`,
    timestamp: new Date().toISOString(),
    metadata: { subtaskCount: plan.subtasks.length, estimatedTokens: plan.estimatedTokens },
  });

  await db.task.update({
    where: { id: taskId },
    data: { status: "RUNNING" },
  });

  // Build a rolling context of prior outputs
  let priorContext = "";

  // Execute subtasks respecting dependencies
  for (const subtask of plan.subtasks) {
    // Check dependencies are completed
    if (subtask.dependsOn && subtask.dependsOn.length > 0) {
      const depsOk = subtask.dependsOn.every((depIdx) =>
        subtaskResults.some((r) => r.subtask.idx === depIdx && r.subtask.status === "COMPLETED")
      );
      if (!depsOk) {
        subtask.status = "SKIPPED";
        continue;
      }
    }

    const updatedSubtask: Subtask = { ...subtask, status: "RUNNING", startedAt: new Date().toISOString() };

    try {
      const result = await executeSubtask(updatedSubtask, userRequest, taskId, priorContext);
      updatedSubtask.status = "COMPLETED";
      updatedSubtask.result = result.result;
      updatedSubtask.artifacts = result.artifacts.map((a) => a.name);
      updatedSubtask.completedAt = new Date().toISOString();
      updatedSubtask.tokensUsed = result.tokensUsed;

      subtaskResults.push({
        subtask: updatedSubtask,
        result: result.result,
        tokensUsed: result.tokensUsed,
        cost: result.cost,
      });
      allArtifacts.push(...result.artifacts);
      allEvents.push(...result.events);
      totalTokens += result.tokensUsed;
      totalCost += result.cost;

      // Append this subtask's output to the rolling context (capped)
      priorContext += `### ${updatedSubtask.title} (${PROVIDERS[updatedSubtask.provider as Provider].displayName})\n${result.result.slice(0, 1500)}\n\n`;

      // Update task progress
      await db.task.update({
        where: { id: taskId },
        data: {
          planJson: JSON.stringify(plan.subtasks.map((s) => (s.idx === subtask.idx ? updatedSubtask : s))),
          eventsJson: JSON.stringify(allEvents.slice(-25)),
          artifactsJson: JSON.stringify(allArtifacts),
          usedTokens: totalTokens,
          estimatedCost: totalCost,
        },
      });
    } catch (err) {
      console.error(`[Task ${taskId}] Subtask ${subtask.idx} failed:`, err);
      updatedSubtask.status = "FAILED";
      updatedSubtask.error = err instanceof Error ? err.message : "Unknown error";
      subtaskResults.push({
        subtask: updatedSubtask,
        result: "",
        tokensUsed: 0,
        cost: 0,
      });

      allEvents.push({
        id: `evt-${taskId}-${subtask.idx}-failed`,
        taskId,
        type: "TASK_FAILED",
        message: `Subtask ${subtask.idx + 1} failed: ${updatedSubtask.error}`,
        provider: subtask.provider,
        subtaskIdx: subtask.idx,
        timestamp: new Date().toISOString(),
      });
    }
  }

  // Verification phase
  await db.task.update({ where: { id: taskId }, data: { status: "VERIFYING" } });

  allEvents.push({
    id: `evt-${taskId}-verify-start`,
    taskId,
    type: "VERIFICATION_STARTED",
    message: "Starting independent verification of combined outputs",
    timestamp: new Date().toISOString(),
  });

  const verification = verifyTask(plan, subtaskResults.map((r) => ({ subtask: r.subtask, result: r.result })));

  allEvents.push({
    id: `evt-${taskId}-verify-done`,
    taskId,
    type: verification.passed ? "TASK_COMPLETED" : "CORRECTION_REQUESTED",
    message: verification.summary,
    timestamp: new Date().toISOString(),
    metadata: {
      checks: verification.checks.length,
      passed: verification.checks.filter((c) => c.passed).length,
      totalCost: totalCost,
      totalTokens: totalTokens,
    },
  });

  const finalStatus = verification.passed ? "COMPLETED" : "FAILED";

  // Record usage per provider
  const task = await db.task.findUnique({ where: { id: taskId } });
  if (task) {
    for (const r of subtaskResults) {
      if (r.tokensUsed > 0) {
        await db.usageRecord.create({
          data: {
            userId: task.userId,
            taskId,
            provider: r.subtask.provider,
            model: ENGINE_MODELS[r.subtask.provider as Provider]?.model || "unknown",
            inputTokens: Math.round(r.tokensUsed * 0.4),
            outputTokens: Math.round(r.tokensUsed * 0.6),
            cost: r.cost,
            durationMs: 1000,
            success: r.subtask.status === "COMPLETED",
          },
        });
      }
    }
  }

  await db.task.update({
    where: { id: taskId },
    data: {
      status: finalStatus,
      verificationJson: JSON.stringify(verification),
      usedTokens: totalTokens,
      estimatedCost: totalCost,
      completedAt: new Date(),
      eventsJson: JSON.stringify(allEvents.slice(-40)),
      artifactsJson: JSON.stringify(allArtifacts),
      planJson: JSON.stringify(subtaskResults.map((r) => r.subtask)),
    },
  });
}
